internal static class Deployment {
 internal const string RegistryPath=@"SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall\LineInputLowLatency";
 static bool IsAdmin(){return new WindowsPrincipal(WindowsIdentity.GetCurrent()).IsInRole(WindowsBuiltInRole.Administrator);}
 internal static string Marker {get{return Path.Combine(Common.Install,"installation.json");}}
 internal static void CheckRoot(bool requireMarker){string expected=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.ProgramFiles),Common.Product);if(!String.Equals(Path.GetFullPath(Common.Install),Path.GetFullPath(expected),StringComparison.OrdinalIgnoreCase))throw new IOException("インストール先が不正です。");if(Directory.Exists(expected)&&(File.GetAttributes(expected)&FileAttributes.ReparsePoint)!=0)throw new IOException("リンク先へのインストール・削除は行いません。");if(requireMarker&&Common.Text(Common.ReadJson(Marker),"ProductId","")!=Common.ProductId)throw new IOException("このアプリのインストール先であることを確認できません。");}
 internal static void InstallElevated(){if(!IsAdmin())throw new UnauthorizedAccessException("管理者権限が必要です。");CheckRoot(false);if(Directory.Exists(Common.Install)&&Directory.GetFileSystemEntries(Common.Install).Length>0)CheckRoot(true);Directory.CreateDirectory(Common.Install);
  using(var stream=Assembly.GetExecutingAssembly().GetManifestResourceStream("payload.zip")){if(stream==null)throw new IOException("インストールデータがありません。");using(var zip=new ZipArchive(stream,ZipArchiveMode.Read)){foreach(var entry in zip.Entries){if(String.IsNullOrEmpty(entry.Name)||entry.FullName!=entry.Name||entry.Name.Contains(".."))throw new IOException("不正なインストールデータです。");string target=Path.Combine(Common.Install,entry.Name);using(var input=entry.Open())using(var output=new FileStream(target,FileMode.Create,FileAccess.Write)){input.CopyTo(output);}}}}
  foreach(string oldName in new[]{"SoundVolumeView.exe","NirSoft-Readme.txt"}){string old=Path.Combine(Common.Install,oldName);if(File.Exists(old))File.Delete(old);}Common.WriteJson(Marker,new{ProductId=Common.ProductId,Version=Common.Version,InstalledAt=DateTime.Now.ToString("o")});
  using(var key=Registry.LocalMachine.CreateSubKey(RegistryPath)){key.SetValue("DisplayName","ライン入力モニター");key.SetValue("DisplayVersion",Common.Version);key.SetValue("Publisher","ryuya0124");key.SetValue("InstallLocation",Common.Install);key.SetValue("DisplayIcon",Path.Combine(Common.Install,"LineInputLowLatency.exe"));key.SetValue("UninstallString","\""+Path.Combine(Common.Install,"Uninstall.exe")+"\"");key.SetValue("NoModify",1,RegistryValueKind.DWord);key.SetValue("NoRepair",1,RegistryValueKind.DWord);}
 }
 internal static void ExtractSources(){Directory.CreateDirectory(Common.Source);using(var stream=Assembly.GetExecutingAssembly().GetManifestResourceStream("sources.zip")){if(stream==null)return;string archive=Path.Combine(Common.Source,"Source-"+Common.Version+".zip");using(var output=File.Create(archive))stream.CopyTo(output);if(!Directory.Exists(Path.Combine(Common.Source,"src"))){string prefix=Path.GetFullPath(Common.Source)+Path.DirectorySeparatorChar;using(var zip=ZipFile.OpenRead(archive))foreach(var entry in zip.Entries){if(String.IsNullOrEmpty(entry.Name))continue;string target=Path.GetFullPath(Path.Combine(Common.Source,entry.FullName.Replace('/',Path.DirectorySeparatorChar)));if(!target.StartsWith(prefix,StringComparison.OrdinalIgnoreCase))throw new IOException("Unsafe source path");Directory.CreateDirectory(Path.GetDirectoryName(target));if(!File.Exists(target))entry.ExtractToFile(target);}}}}
 internal static void StartApp(){string args=String.IsNullOrEmpty(Common.Text(Common.ReadJson(Path.Combine(Common.Data,"settings.json")),"InputId",""))?"":"--background";Process.Start(new ProcessStartInfo(Path.Combine(Common.Install,"LineInputLowLatency.exe"),args){UseShellExecute=true});}
 internal static void InstallUserEntries(){string exe=Path.Combine(Common.Install,"LineInputLowLatency.exe");Common.Startup(true,exe);Common.Shortcut(Path.Combine(Common.MenuFolder,"ライン入力モニター.lnk"),exe,"");Common.Shortcut(Path.Combine(Common.MenuFolder,"アンインストール.lnk"),Path.Combine(Common.Install,"Uninstall.exe"),"");}
 internal static void UninstallElevated(){if(!IsAdmin())throw new UnauthorizedAccessException("管理者権限が必要です。");CheckRoot(true);Common.StopInstalledApp();Directory.Delete(Common.Install,true);using(var root=Registry.LocalMachine.OpenSubKey(@"SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall",true)){if(root!=null)root.DeleteSubKeyTree(Common.Product,false);}}
 internal static void RemoveUserEntries(bool removeData){if(File.Exists(Common.StartupLink))File.Delete(Common.StartupLink);if(Directory.Exists(Common.MenuFolder)&&String.Equals(Path.GetFullPath(Common.MenuFolder),Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.Programs),"ライン入力モニター"),StringComparison.OrdinalIgnoreCase))Directory.Delete(Common.MenuFolder,true);if(removeData&&Directory.Exists(Common.Data)){string expected=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),Common.Product);if(!String.Equals(Path.GetFullPath(Common.Data),Path.GetFullPath(expected),StringComparison.OrdinalIgnoreCase)||(File.GetAttributes(Common.Data)&FileAttributes.ReparsePoint)!=0)throw new IOException("設定フォルダーの削除先を確認できません。");Directory.Delete(Common.Data,true);}}
 internal static void RestoreAudio(){Common.StopInstalledApp();try{Common.RestoreIfNeeded(Common.Install);}catch{}}
 internal static void ValidatePackage(){var required=new HashSet<string>(StringComparer.OrdinalIgnoreCase){"LineInputLowLatency.exe","AudioEngine.exe","AudioSettings.exe","Uninstall.exe"};using(var stream=Assembly.GetExecutingAssembly().GetManifestResourceStream("payload.zip")){if(stream==null)throw new IOException("Package resource missing");using(var zip=new ZipArchive(stream,ZipArchiveMode.Read)){foreach(var e in zip.Entries){if(e.Name!=e.FullName||e.Name.Contains(".."))throw new IOException("Unsafe package path");string ext=Path.GetExtension(e.Name).ToLowerInvariant();if(ext==".py"||ext==".ps1"||ext==".bat"||ext==".cmd")throw new IOException("Forbidden script in package");required.Remove(e.Name);}}}if(required.Count>0)throw new IOException("Package files missing");}
 internal static void SelfTest(){ValidatePackage();string temp=Path.GetFullPath(Path.Combine(Path.GetTempPath(),"LineInputLowLatency-SelfTest-"+Guid.NewGuid().ToString("N")));string prefix=Path.GetFullPath(Path.GetTempPath())+"LineInputLowLatency-SelfTest-";if(!temp.StartsWith(prefix,StringComparison.OrdinalIgnoreCase))throw new IOException("Unsafe test destination");Directory.CreateDirectory(temp);using(var resource=Assembly.GetExecutingAssembly().GetManifestResourceStream("payload.zip"))using(var zip=new ZipArchive(resource,ZipArchiveMode.Read)){foreach(var entry in zip.Entries){if(entry.Name!=entry.FullName||entry.Name.Contains(".."))throw new IOException("Unsafe package entry");entry.ExtractToFile(Path.Combine(temp,entry.Name));}}foreach(string exe in new[]{"LineInputLowLatency.exe","AudioEngine.exe","AudioSettings.exe","Uninstall.exe"}){using(var f=File.OpenRead(Path.Combine(temp,exe))){if(f.ReadByte()!=77||f.ReadByte()!=90)throw new IOException("Invalid executable");}}Common.WriteJson(Path.Combine(temp,"installation.json"),new{ProductId=Common.ProductId});if(Common.Text(Common.ReadJson(Path.Combine(temp,"installation.json")),"ProductId","")!=Common.ProductId||(File.GetAttributes(temp)&FileAttributes.ReparsePoint)!=0)throw new IOException("Unsafe uninstall test destination");Directory.Delete(temp,true);Common.WriteJson(Path.Combine(Common.Data,"self-test.json"),new{Success=true,Executables=4,ForbiddenScripts=0,ExtractAndCleanup=true,Time=DateTime.Now.ToString("o")});}
 internal static int ApplyCommand(bool uninstall){RestoreAudio();Directory.CreateDirectory(Common.Data);string result=Path.Combine(Path.GetTempPath(),"LineInputLowLatency-result-"+Guid.NewGuid().ToString("N")+".json");try{using(var child=Process.Start(new ProcessStartInfo(Application.ExecutablePath,(uninstall?"--elevated-uninstall":"--elevated-install")+" \""+result+"\""){UseShellExecute=true,Verb="runas",WindowStyle=ProcessWindowStyle.Hidden,WorkingDirectory=Path.GetDirectoryName(Application.ExecutablePath)})){child.WaitForExit();if(child.ExitCode!=0)throw new IOException(Common.Text(Common.ReadJson(result),"Error","Operation failed"));}if(uninstall)RemoveUserEntries(false);else{ExtractSources();InstallUserEntries();StartApp();}Common.WriteJson(Path.Combine(Common.Data,uninstall?"uninstall-result.json":"install-result.json"),new{Success=true,InstallPath=Common.Install,Startup=File.Exists(Common.StartupLink),Time=DateTime.Now.ToString("o")});return 0;}catch(Exception ex){Common.WriteJson(Path.Combine(Common.Data,uninstall?"uninstall-result.json":"install-result.json"),new{Success=false,Error=ex.ToString()});return 1;}finally{if(File.Exists(result))File.Delete(result);}}
 [DllImport("kernel32.dll",CharSet=CharSet.Unicode,SetLastError=true)]static extern bool MoveFileEx(string source,string target,int flags);
 internal static void ScheduleTempRemoval(){string file=Application.ExecutablePath,stringRoot=Path.GetDirectoryName(file);if(stringRoot.StartsWith(Path.Combine(Path.GetTempPath(),"LineInputLowLatency-Uninstall-"),StringComparison.OrdinalIgnoreCase)){MoveFileEx(file,null,4);MoveFileEx(stringRoot,null,4);}}
}
internal sealed class SetupForm : Form {
 readonly bool uninstall;readonly Button action=new Button(),close=new Button();readonly Label message=new Label();readonly CheckBox removeData=new CheckBox();bool busy;
 internal SetupForm(bool uninstall){this.uninstall=uninstall;AutoScaleMode=AutoScaleMode.None;Text=uninstall?"ライン入力モニターの削除":"ライン入力モニターのインストール";ClientSize=new Size(554,300);FormBorderStyle=FormBorderStyle.FixedDialog;MaximizeBox=false;StartPosition=FormStartPosition.CenterScreen;Font=new Font("Yu Gothic UI",10);Icon=Theme.AppIcon();BackColor=Color.FromArgb(247,249,252);
  var title=new Label{Text=uninstall?"ライン入力モニターを削除":"ライン入力モニターをインストール",Font=new Font("Yu Gothic UI",16,FontStyle.Bold),Location=new Point(24,21),Size=new Size(510,36)};Controls.Add(title);
  message.Text=uninstall?"アプリと自動起動の登録を削除し、元の音声設定へ戻します。\nドキュメントにあるソースコードは残します。":"アプリ本体："+Common.Install+"\nソースコード："+Common.Source+"\nサインイン時に起動し、タスクバーに常駐します。";message.Location=new Point(26,77);message.Size=new Size(505,145);Controls.Add(message);
  removeData.Text="設定とログも削除する";removeData.Location=new Point(27,181);removeData.Size=new Size(400,28);removeData.Visible=uninstall;Controls.Add(removeData);
  action.Text=uninstall?"アンインストール":"インストール";action.Location=new Point(278,238);action.Size=new Size(156,36);Controls.Add(action);close.Text="閉じる";close.Location=new Point(447,238);close.Size=new Size(80,36);Controls.Add(close);close.Click+=(s,e)=>Close();action.Click+=async(s,e)=>await Apply();FormClosing+=(s,e)=>{if(busy)e.Cancel=true;};Theme.Apply(this,Theme.Saved);
 }
 async Task Apply(){busy=true;action.Enabled=false;close.Enabled=false;try{Deployment.RestoreAudio();string result=Path.Combine(Path.GetTempPath(),"LineInputLowLatency-result-"+Guid.NewGuid().ToString("N")+".json");var info=new ProcessStartInfo(Application.ExecutablePath,(uninstall?"--elevated-uninstall":"--elevated-install")+" \""+result+"\""){UseShellExecute=true,Verb="runas",WindowStyle=ProcessWindowStyle.Hidden,WorkingDirectory=Path.GetDirectoryName(Application.ExecutablePath)};int code=await Task.Run(()=>{using(var p=Process.Start(info)){p.WaitForExit();return p.ExitCode;}});var record=Common.ReadJson(result);if(File.Exists(result))File.Delete(result);if(code!=0)throw new IOException(Common.Text(record,"Error","操作を完了できませんでした。"));if(uninstall){Deployment.RemoveUserEntries(removeData.Checked);message.Text="アンインストールが完了しました。\n元の音声設定へ戻しました。ソースコードは保持しています。";}else{Deployment.ExtractSources();Deployment.InstallUserEntries();Deployment.StartApp();message.Text="インストールが完了しました。\nアプリを起動し、自動起動も登録しました。";}action.Visible=false;removeData.Visible=false;}
 catch(System.ComponentModel.Win32Exception ex){message.Text=ex.NativeErrorCode==1223?"Windowsの確認がキャンセルされました。\nインストール内容は変更していません。":ex.Message;action.Enabled=true;}
 catch(Exception ex){message.Text=ex.Message;action.Enabled=true;}
 finally{busy=false;close.Enabled=true;}}
}
internal static class InstallerProgram {
 [STAThread]static int Main(string[]args){Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);
  if(args.Length==2&&(args[0]=="--elevated-install"||args[0]=="--elevated-uninstall")){try{if(args[0]=="--elevated-install")Deployment.InstallElevated();else Deployment.UninstallElevated();Common.WriteJson(args[1],new{Success=true});Deployment.ScheduleTempRemoval();return 0;}catch(Exception ex){try{Common.WriteJson(args[1],new{Success=false,Error=ex.ToString()});}catch{}return 1;}}
  bool uninstall=Path.GetFileNameWithoutExtension(Application.ExecutablePath).StartsWith("Uninstall",StringComparison.OrdinalIgnoreCase);
  if(args.Length==1&&args[0]=="--validate-package"){try{Deployment.ValidatePackage();Common.WriteJson(Path.Combine(Common.Data,"package-check.json"),new{Success=true});return 0;}catch(Exception ex){Common.WriteJson(Path.Combine(Common.Data,"package-check.json"),new{Success=false,Error=ex.ToString()});return 1;}}
  if(args.Length==1&&args[0]=="--self-test"){try{Deployment.SelfTest();return 0;}catch(Exception ex){Common.WriteJson(Path.Combine(Common.Data,"self-test.json"),new{Success=false,Error=ex.ToString()});return 1;}}
  if(args.Length==2&&args[0]=="--render-preview"){using(var form=new SetupForm(uninstall)){form.ShowInTaskbar=false;form.StartPosition=FormStartPosition.Manual;form.Location=new Point(-30000,-30000);form.Show();form.Update();using(var bitmap=new Bitmap(form.Width,form.Height)){form.DrawToBitmap(bitmap,new Rectangle(Point.Empty,bitmap.Size));bitmap.Save(args[1]);}}return 0;}
  if(uninstall&&Application.ExecutablePath.StartsWith(Common.Install+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase)){string temp=Path.Combine(Path.GetTempPath(),"LineInputLowLatency-Uninstall-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(temp);string copy=Path.Combine(temp,"Uninstall.exe");File.Copy(Application.ExecutablePath,copy);Process.Start(new ProcessStartInfo(copy,String.Join(" ",args)){UseShellExecute=true,WorkingDirectory=temp});return 0;}
  if(args.Length==1&&(args[0]=="--install"||args[0]=="--uninstall"))return Deployment.ApplyCommand(args[0]=="--uninstall");
  Application.Run(new SetupForm(uninstall));return 0;
 }
}
